// Given: styles for the player widget, injected once. Do not edit this file.
const CSS = `
.pfs-player { --pfs-ink:#26251f; --pfs-muted:#6f6d64; --pfs-line:#dcdad2; --pfs-bg:#fbfbf9; --pfs-btn:#f0efe9;
  font: 14px/1.4 system-ui, sans-serif; color: var(--pfs-ink); border: 1px solid var(--pfs-line);
  border-radius: 8px; overflow: hidden; background: var(--pfs-bg); max-width: 100%; outline: none; }
.pfs-player:focus-visible { box-shadow: 0 0 0 2px #2563c9; }
@media (prefers-color-scheme: dark) {
  .pfs-player { --pfs-ink:#e8e6df; --pfs-muted:#a3a198; --pfs-line:#34343b; --pfs-bg:#17171a; --pfs-btn:#26262c; }
}
.pfs-canvas { display: block; width: 100%; }
.pfs-caption { padding: 8px 12px 0; min-height: 1.4em; }
.pfs-group { color: var(--pfs-muted); }
.pfs-controls { display: flex; align-items: center; gap: 6px; padding: 8px 12px; flex-wrap: wrap; }
.pfs-controls button { min-width: 44px; min-height: 36px; border: 1px solid var(--pfs-line); border-radius: 6px;
  background: var(--pfs-btn); color: var(--pfs-ink); font-size: 12px; cursor: pointer; }
.pfs-controls input[type=range] { flex: 1 1 120px; min-width: 0; }
.pfs-count { color: var(--pfs-muted); font-variant-numeric: tabular-nums; min-width: 4.5em; text-align: right; }
.pfs-values { display: grid; grid-template-columns: max-content 1fr; gap: 2px 12px; margin: 0; padding: 0 12px 10px;
  font: 12px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
.pfs-values dt { color: var(--pfs-muted); }
.pfs-values dd { margin: 0; }
`;

let injected = false;

export function injectStyles(): void {
  if (injected || typeof document === "undefined") return;
  const style = document.createElement("style");
  style.textContent = CSS;
  document.head.appendChild(style);
  injected = true;
}
